    public static int longestStrChain(String[] words) {
        hm = new HashMap<>();
        String[] sortedAscending = Arrays.stream(words)
                .sorted((s1, s2) -> Integer.compare(s1.length(), s2.length()))
                .toArray(String[]::new);
        dp = new Integer[words.length+1][words.length+1];
        return longestStrChainIndex(sortedAscending,0,0,-1);
    }


    private static int longestStrChainIndex(String[] words, int i, int count, int prevIndex) {
        if(i>=words.length) {
            return 0;
        }

        if( Objects.nonNull(dp[i][prevIndex+1])) {
            return dp[i][prevIndex+1];
        }
        int countNotTakingIt = longestStrChainIndex(words,i+1,count,prevIndex);
        String prevString = prevIndex==-1?"":words[prevIndex];
        int countTakingIt = 0;
        boolean comp = customCompare(prevString,words[i]);
        if(comp){
            countTakingIt = 1+longestStrChainIndex(words,i+1,count+1,i);
        }
        int max =  Math.max(countTakingIt,countNotTakingIt);
        dp[i][prevIndex+1] = max;
        return max;

    }
    private static int longestStrChain(String[] words, int i, int count, String prev) {
        if(i>=words.length) {
            return 0;
        }
        String key = i+","+prev;
        boolean z = hashcodes.add(key.hashCode());
        if(!z) {
            countcollisions++;
        }
        if(hm.containsKey(key)) {
            return hm.get(key);
        }
        int countNotTakingIt = longestStrChain(words,i+1,count,prev);
        int countTakingIt = 0;
        boolean comp = customCompare(prev,words[i]);
        if(comp){
            countTakingIt = 1+longestStrChain(words,i+1,count+1,words[i]);
        }
        int max =  Math.max(countTakingIt,countNotTakingIt);
        hm.put(key,max);
        return max;

    }


    private static boolean customCompare(String a, String b) {
        if(a.isEmpty()) return true;
        if(a.length()+1!=b.length()) return false;
            int i=0;
            int j=0;
            while(i<a.length()&&j<b.length()){
                if(a.charAt(i)==b.charAt(j))
                    i++;
                j++;
            }

            if(i==a.length())
                return true;

            return false;


    }


